import {rng,createModel,evaluate} from './inverse-network.mjs';
import {objective,adam,wave,score} from './hidden-core.mjs';
export const CONDITIONS=['data','correct','wrong'];
export const TRUTH={v:.5,D:.01};
export function validateCampaign(c){if(!c||![6,8,12].includes(c.seeds)||![1000,3000].includes(c.steps)||![0,.01].includes(c.noise)||!Number.isInteger(c.firstSeed)||c.firstSeed<1||c.firstSeed>9999)throw Error('Choose 6, 8 or 12 seeds; 1,000 or 3,000 steps; noise 0 or 0.01; starting seed 1–9999.');return c;}
export function observations(seed,noise){const r=rng(seed+42000);return Array.from({length:16},()=>{const x=r(),t=.4*r();return{x,t,y:wave(x,t,TRUTH.v,TRUTH.D)+noise*(r()+r()+r()+r()+r()+r()-3)*Math.sqrt(2)};});}
export function metrics(p,obs){const m=score((x,t)=>evaluate(p,x,t).u,TRUTH);let residual=0;for(let j=0;j<16;j++)for(let i=0;i<16;i++)residual+=evaluate(p,(i+.37)/16,(j+.61)/16,false,TRUTH.v,TRUTH.D).r**2/256;return{...m,trueResidualRMS:Math.sqrt(residual),observationMSE:obs.reduce((s,o)=>s+(evaluate(p,o.x,o.t).u-o.y)**2,0)/obs.length};}
function shuffle(a,r){for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function startingModel(seed,donor=null,scramble=false){const m=createModel(seed);if(donor){const random=rng(seed+61000);for(let k=1;k<=4;k++){const col=Array.from({length:32},(_,j)=>donor[1+5*j+k]);if(scramble)shuffle(col,random);for(let j=0;j<32;j++)m.p[1+5*j+k]=col[j];}}return m;}
export function trainRun(seed,condition,c,donor=null,progress=()=>{}){const obs=observations(seed,c.noise),m=startingModel(seed,donor,condition==='scrambled'),random=rng(seed+43000),v=condition==='wrong'?-.5:.5,weight=condition==='data'?0:.1;const checkpoints=[];const snapshot=step=>checkpoints.push({step,weights:Array.from(m.p),metrics:metrics(m.p,obs)});snapshot(0);for(let i=1;i<=c.steps;i++){const pts=Array.from({length:32},()=>({x:random(),t:random()}));const l=objective(m.p,obs,pts,v,.01,weight);adam(m,l.g);if(i%250===0){if(i%(c.steps/4)===0)snapshot(i);progress(i);}}return{seed,condition,observations:obs,checkpoints,metrics:checkpoints.at(-1).metrics,delta:Array.from(m.p,(v,i)=>v-checkpoints[0].weights[i]),physics:{v,D:.01,weight},donorSeed:donor?c.firstSeed:null};}
export function runCampaign(config,onProgress=()=>{}){const c=validateCampaign(config),seeds=Array.from({length:c.seeds},(_,i)=>c.firstSeed+i),split=c.seeds/2,discoverySeeds=seeds.slice(0,split),confirmationSeeds=seeds.slice(split),runs=[],total=c.seeds*3+confirmationSeeds.length*2;let donor;const add=(seed,condition)=>{const run=trainRun(seed,condition,c,['transfer','scrambled'].includes(condition)?donor:null,step=>onProgress({completed:runs.length,total,seed,condition,step,steps:c.steps}));run.split=discoverySeeds.includes(seed)?'discovery':'confirmation';runs.push(run);if(seed===c.firstSeed&&condition==='correct')donor=run.checkpoints.at(-1).weights;};for(const seed of seeds)for(const condition of CONDITIONS)add(seed,condition);for(const seed of confirmationSeeds)for(const condition of ['transfer','scrambled'])add(seed,condition);return{format:'transport-isomorph-v1',created:new Date().toISOString(),config:c,architecture:{id:'periodic-tanh32-v1',weights:161,inputs:['sin(2πx)','cos(2πx)','2t−1'],layout:'bias, then 32 groups of [output,sin,cos,time,bias]'},truth:TRUTH,protocol:{discoverySeeds,confirmationSeeds,donorSeed:c.firstSeed,transfer:'Copy hidden input weights and biases from the first discovery correct-physics run; reset output weights and Adam state. Train all weights.',control:'Independently shuffle each of four donor hidden input/bias columns; same output initialization and training.',fixedHypothesis:'Transferred hidden features improve confirmation forecast RMSE relative to random initialization and the column-shuffled donor.',limits:'Same equation and initial condition across runs; different initialization and observations. Fourier features are supplied. This tests same-task transfer, not cross-domain laws. Donor pretraining cost is additional.',alignmentFitDomain:{t:[0,.4]},evaluationDomain:{t:[.4,1]}},runs};}
